import unittest

import hourglass.errors
import hourglass.models
import hourglass.timesheet


class TimesheetRowsTests(unittest.TestCase):
    def test_busiest_worker_first(self):
        shifts = [
            hourglass.models.Shift("Odell", "mon", hourglass.models.Span(540, 900)),
            hourglass.models.Shift("Brisa", "mon", hourglass.models.Span(540, 780)),
            hourglass.models.Shift("Brisa", "wed", hourglass.models.Span(840, 1020)),
        ]
        self.assertTrue(
            hourglass.timesheet.timesheet_rows(shifts)
            == ["Brisa, 2 shifts, 7.0 hours", "Odell, 1 shifts, 6.0 hours"]
        )

    def test_ties_broken_by_name(self):
        shifts = [
            hourglass.models.Shift("Zed", "mon", hourglass.models.Span(540, 600)),
            hourglass.models.Shift("Amos", "mon", hourglass.models.Span(660, 720)),
        ]
        self.assertTrue(
            hourglass.timesheet.timesheet_rows(shifts)
            == ["Amos, 1 shifts, 1.0 hours", "Zed, 1 shifts, 1.0 hours"]
        )

    def test_hours_round_half_up(self):
        shifts = [
            hourglass.models.Shift("Quill", "mon", hourglass.models.Span(540, 675)),
        ]
        self.assertTrue(
            hourglass.timesheet.timesheet_rows(shifts)
            == ["Quill, 1 shifts, 2.3 hours"]
        )

    def test_empty_list_raises(self):
        with self.assertRaises(hourglass.errors.ProjectError):
            hourglass.timesheet.timesheet_rows([])

    def test_blank_worker_raises(self):
        shifts = [
            hourglass.models.Shift("Brisa", "mon", hourglass.models.Span(540, 600)),
            hourglass.models.Shift("   ", "mon", hourglass.models.Span(600, 660)),
        ]
        with self.assertRaises(hourglass.errors.ProjectError):
            hourglass.timesheet.timesheet_rows(shifts)
